"use client";

import * as React from "react";
import { X } from "lucide-react";
import { t } from "@/lib/i18n";

export interface DialogProps {
  open: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
  /** Optional footer (e.g. action buttons). */
  footer?: React.ReactNode;
}

/**
 * Modal dialog built on the native <dialog> element, which gives us focus
 * trapping, Esc-to-close, and inert background for free. Labelled by its title.
 */
export function Dialog({ open, onClose, title, children, footer }: DialogProps) {
  const ref = React.useRef<HTMLDialogElement>(null);
  const titleId = React.useId();

  React.useEffect(() => {
    const dialog = ref.current;
    if (!dialog) return;
    if (open && !dialog.open) {
      // showModal isn't implemented in jsdom; fall back to the open attribute.
      try {
        dialog.showModal();
      } catch {
        dialog.open = true;
      }
    } else if (!open && dialog.open) {
      try {
        dialog.close();
      } catch {
        dialog.open = false;
      }
    }
  }, [open]);

  return (
    <dialog
      ref={ref}
      aria-labelledby={titleId}
      onClose={onClose}
      onClick={(e) => {
        // Close when the backdrop (the dialog element itself) is clicked.
        if (e.target === ref.current) onClose();
      }}
      className="m-auto w-[min(92vw,32rem)] rounded-lg border border-border bg-surface p-0 text-ink shadow-lg backdrop:bg-ink/40"
    >
      <div className="flex items-start justify-between gap-4 border-b border-border px-6 pt-5 pb-4">
        <h2 id={titleId} className="text-h3">
          {title}
        </h2>
        <button
          type="button"
          onClick={onClose}
          aria-label={t("safety.close")}
          className="-m-2 rounded-sm p-2 text-ink-soft hover:text-ink"
        >
          <X size={22} strokeWidth={2} aria-hidden="true" />
        </button>
      </div>
      <div className="px-6 py-5">{children}</div>
      {footer ? (
        <div className="flex flex-wrap justify-end gap-3 border-t border-border px-6 py-4">
          {footer}
        </div>
      ) : null}
    </dialog>
  );
}

"use client";

import * as React from "react";
import { Mic, Square, Play, Pause, Upload, CircleCheck } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { createClient } from "@/lib/supabase/client";
import { VOICE_BUCKET } from "@/lib/constants";
import { t } from "@/lib/i18n";
import { useToast } from "@/components/ui/Toast";

interface Props {
  providerId: string;
  /** Existing stored path, if any. */
  initialPath?: string | null;
  onUploaded: (path: string | null) => void;
}

/**
 * Record (MediaRecorder) or upload a voice intro and store it in the private
 * voice-intros bucket. Fully labelled, keyboard-operable; degrades to file
 * upload where recording isn't available. Audio is optional — the written
 * intro is the accessible equivalent.
 */
export function VoiceIntroRecorder({ providerId, initialPath, onUploaded }: Props) {
  const { announce } = useToast();
  const [recording, setRecording] = React.useState(false);
  const [audioUrl, setAudioUrl] = React.useState<string | null>(null);
  const [playing, setPlaying] = React.useState(false);
  const [uploading, setUploading] = React.useState(false);
  const [hasIntro, setHasIntro] = React.useState(!!initialPath);
  const [error, setError] = React.useState<string | null>(null);

  const recorderRef = React.useRef<MediaRecorder | null>(null);
  const chunksRef = React.useRef<Blob[]>([]);
  const audioRef = React.useRef<HTMLAudioElement | null>(null);

  const canRecord =
    typeof window !== "undefined" &&
    typeof window.MediaRecorder !== "undefined" &&
    !!navigator.mediaDevices?.getUserMedia;

  async function upload(blob: Blob) {
    setUploading(true);
    setError(null);
    try {
      const supabase = createClient();
      const path = `${providerId}/intro.webm`;
      const { error: upErr } = await supabase.storage
        .from(VOICE_BUCKET)
        .upload(path, blob, {
          upsert: true,
          contentType: blob.type || "audio/webm",
        });
      if (upErr) throw upErr;
      setHasIntro(true);
      onUploaded(path);
      announce(t("provider.recordingReady"));
    } catch {
      setError(t("provider.recordingUnsupported"));
    } finally {
      setUploading(false);
    }
  }

  async function startRecording() {
    setError(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      chunksRef.current = [];
      recorder.ondataavailable = (e) => chunksRef.current.push(e.data);
      recorder.onstop = () => {
        const blob = new Blob(chunksRef.current, { type: "audio/webm" });
        if (audioUrl) URL.revokeObjectURL(audioUrl);
        setAudioUrl(URL.createObjectURL(blob));
        stream.getTracks().forEach((track) => track.stop());
        void upload(blob);
      };
      recorderRef.current = recorder;
      recorder.start();
      setRecording(true);
      announce(t("provider.recordLabel"));
    } catch {
      setError(t("provider.recordingUnsupported"));
    }
  }

  function stopRecording() {
    recorderRef.current?.stop();
    setRecording(false);
  }

  function togglePlay() {
    const el = audioRef.current;
    if (!el) return;
    if (playing) {
      el.pause();
      setPlaying(false);
    } else {
      void el.play();
      setPlaying(true);
    }
  }

  async function onFile(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;
    if (audioUrl) URL.revokeObjectURL(audioUrl);
    setAudioUrl(URL.createObjectURL(file));
    await upload(file);
  }

  return (
    <div className="flex flex-col gap-4 rounded-card border border-border bg-surface p-5">
      <div className="flex flex-wrap items-center gap-3">
        {canRecord && !recording ? (
          <Button icon={Mic} onClick={startRecording} disabled={uploading}>
            {hasIntro ? t("provider.rerecordLabel") : t("provider.recordLabel")}
          </Button>
        ) : null}
        {recording ? (
          <Button variant="danger" icon={Square} onClick={stopRecording}>
            {t("provider.stopLabel")}
          </Button>
        ) : null}

        {audioUrl ? (
          <Button
            variant="ghost"
            icon={playing ? Pause : Play}
            onClick={togglePlay}
          >
            {playing ? t("provider.pauseLabel") : t("provider.playLabel")}
          </Button>
        ) : null}

        <label className="inline-flex min-h-12 cursor-pointer items-center gap-2 rounded-btn border border-border-strong bg-surface px-4 text-base font-bold text-primary hover:bg-primary-tint">
          <Upload size={20} strokeWidth={2} aria-hidden="true" />
          {t("provider.uploadLabel")}
          <input
            type="file"
            accept="audio/*"
            className="sr-only"
            onChange={onFile}
            disabled={uploading}
          />
        </label>
      </div>

      <p className="flex items-center gap-2 text-base text-ink-soft" aria-live="polite">
        {hasIntro ? (
          <>
            <CircleCheck
              size={18}
              strokeWidth={2}
              aria-hidden="true"
              className="text-success"
            />
            {t("provider.recordingReady")}
          </>
        ) : uploading ? (
          t("ui.loading")
        ) : (
          t("provider.recordingNone")
        )}
      </p>

      {error ? (
        <p role="alert" className="text-base font-semibold text-alert">
          {error}
        </p>
      ) : null}

      {audioUrl ? (
        <audio
          ref={audioRef}
          src={audioUrl}
          onEnded={() => setPlaying(false)}
          className="sr-only"
        />
      ) : null}
    </div>
  );
}

import "server-only";
import { createServerClient, type CookieOptions } from "@supabase/ssr";
import { cookies } from "next/headers";
import { type Database } from "@/lib/supabase/types";
import { supabaseAnonKey, supabaseUrl } from "@/lib/supabase/env";

/**
 * Server Supabase client bound to the request cookies (anon key, RLS-enforced).
 * Use in Server Components, Server Actions, and Route Handlers.
 */
export async function createClient() {
  const cookieStore = await cookies();

  return createServerClient<Database>(supabaseUrl(), supabaseAnonKey(), {
    cookies: {
      getAll() {
        return cookieStore.getAll();
      },
      setAll(
        cookiesToSet: { name: string; value: string; options?: CookieOptions }[],
      ) {
        try {
          for (const { name, value, options } of cookiesToSet) {
            cookieStore.set(name, value, options);
          }
        } catch {
          // `setAll` called from a Server Component — safe to ignore; the
          // middleware refreshes the session cookie on each request.
        }
      },
    },
  });
}

/**
 * The single source of truth for all pricing & accounting (CLAUDE.md rule 3).
 * Pure functions only — no DB, no side effects. Money is ALWAYS integer cents;
 * never use floats to represent money. The commission rate comes from config
 * (PLATFORM_COMMISSION_RATE), never a literal.
 *
 * No pricing math may live anywhere else in the codebase.
 */

export type BlockMinutes = 15 | 30 | 45;

/** Minimal provider shape needed to price a block. */
export interface BlockPricing {
  price_block_15_cents: number;
  price_block_30_cents: number;
  price_block_45_cents: number;
}

const DEFAULT_COMMISSION_RATE = 0.05;

/** Platform commission rate from config, clamped to [0, 1]; 0.05 fallback. */
export function getCommissionRate(): number {
  const raw = Number(process.env.PLATFORM_COMMISSION_RATE ?? DEFAULT_COMMISSION_RATE);
  if (!Number.isFinite(raw) || raw < 0 || raw > 1) return DEFAULT_COMMISSION_RATE;
  return raw;
}

/** Round to the nearest cent, half-up. Inputs are non-negative money amounts. */
export function roundHalfUp(value: number): number {
  return Math.floor(value + 0.5);
}

/** The block price (cents) a customer authorises at booking time. */
export function priceForBlock(
  provider: BlockPricing,
  blockMinutes: BlockMinutes,
): number {
  switch (blockMinutes) {
    case 15:
      return provider.price_block_15_cents;
    case 30:
      return provider.price_block_30_cents;
    case 45:
      return provider.price_block_45_cents;
  }
}

/** Whole minutes run past the block (rounded up); 0 within the block. */
export function overageMinutes(
  elapsedSeconds: number,
  blockMinutes: BlockMinutes,
): number {
  const overSeconds = elapsedSeconds - blockMinutes * 60;
  if (overSeconds <= 0) return 0;
  return Math.ceil(overSeconds / 60);
}

export interface SessionAccountingInput {
  priceBlockCents: number;
  overagePerMinCents: number;
  elapsedSeconds: number;
  blockMinutes: BlockMinutes;
  /** Defaults to the configured platform rate. */
  commissionRate?: number;
}

export interface SessionAccounting {
  overageMinutes: number;
  totalCents: number;
  commissionCents: number;
  providerEarningsCents: number;
}

/**
 * Final accounting at session end: block + overage → total, commission (half-up)
 * from config, provider keeps the rest. Tips are added later (addTip) and are
 * NOT subject to commission.
 */
export function computeSessionAccounting({
  priceBlockCents,
  overagePerMinCents,
  elapsedSeconds,
  blockMinutes,
  commissionRate = getCommissionRate(),
}: SessionAccountingInput): SessionAccounting {
  const overage = overageMinutes(elapsedSeconds, blockMinutes);
  const totalCents = priceBlockCents + overage * overagePerMinCents;
  const commissionCents = roundHalfUp(totalCents * commissionRate);
  const providerEarningsCents = totalCents - commissionCents;
  return {
    overageMinutes: overage,
    totalCents,
    commissionCents,
    providerEarningsCents,
  };
}

/** Add a tip to provider earnings. Tips carry no platform commission. */
export function addTip(providerEarningsCents: number, tipCents: number): number {
  return providerEarningsCents + Math.max(0, tipCents);
}

export interface CancellationInput {
  priceBlockCents: number;
  /** ISO time of a scheduled session, if any. */
  scheduledAt?: string | null;
  /** "Now" in epoch ms (injected for testability). */
  nowMs: number;
}

export interface CancellationOutcome {
  /** "release" fully releases the hold; "charge" captures the full block. */
  action: "release" | "charge";
  captureCents: number;
}

const ONE_HOUR_MS = 60 * 60 * 1000;

/**
 * Cancellation policy (SPEC §5): cancelling a scheduled session ≥1h before its
 * start fully releases the hold; otherwise the full block is charged. (Ending an
 * in-progress call early still charges the full block — handled naturally by
 * computeSessionAccounting, since elapsed < block yields zero overage.)
 */
export function cancellationOutcome({
  priceBlockCents,
  scheduledAt,
  nowMs,
}: CancellationInput): CancellationOutcome {
  if (scheduledAt) {
    const startMs = new Date(scheduledAt).getTime();
    if (Number.isFinite(startMs) && startMs - nowMs >= ONE_HOUR_MS) {
      return { action: "release", captureCents: 0 };
    }
  }
  return { action: "charge", captureCents: priceBlockCents };
}

import en from "@/messages/en.json";

/**
 * Tiny, dependency-free i18n helper. English-only for now, but the app reads
 * every user-facing string through `t()` so the catalog can be swapped or
 * extended later (see CLAUDE.md rule 7). No hard-coded UI strings in components.
 */

type Messages = typeof en;

/** Dotted key paths into the message catalog, e.g. "auth.signInTitle". */
type DottedKeys<T, Prefix extends string = ""> = {
  [K in keyof T & string]: T[K] extends string
    ? `${Prefix}${K}`
    : DottedKeys<T[K], `${Prefix}${K}.`>;
}[keyof T & string];

export type MessageKey = DottedKeys<Messages>;

function lookup(key: string): string | undefined {
  return key
    .split(".")
    .reduce<unknown>(
      (acc, part) =>
        acc && typeof acc === "object"
          ? (acc as Record<string, unknown>)[part]
          : undefined,
      en,
    ) as string | undefined;
}

/**
 * Resolve a message by key, with optional `{name}`-style interpolation.
 * Returns the key itself if missing so a gap is visible rather than silent.
 */
export function t(
  key: MessageKey,
  vars?: Record<string, string | number>,
): string {
  const raw = lookup(key);
  if (typeof raw !== "string") {
    if (process.env.NODE_ENV !== "production") {
      console.warn(`[i18n] missing message for key: ${key}`);
    }
    return key;
  }
  if (!vars) return raw;
  return raw.replace(/\{(\w+)\}/g, (match, name: string) =>
    name in vars ? String(vars[name]) : match,
  );
}

import * as React from "react";
import { type LucideIcon } from "lucide-react";

type Variant = "primary" | "amber" | "ghost" | "danger" | "quiet";

const VARIANTS: Record<Variant, string> = {
  primary: "bg-primary text-surface hover:bg-primary-dark border-transparent",
  amber: "bg-accent text-surface hover:bg-accent-dark border-transparent",
  ghost:
    "bg-surface text-primary border-border-strong hover:bg-primary-tint",
  danger: "bg-alert text-surface hover:brightness-95 border-transparent",
  quiet:
    "bg-transparent text-primary underline underline-offset-[3px] hover:text-primary-dark border-transparent min-h-0 px-1.5 py-2",
};

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: Variant;
  /** Optional leading icon. Always paired with the button's text label. */
  icon?: LucideIcon;
  full?: boolean;
}

/**
 * Accessible button primitive. ≥48px tap target, visible focus ring (from
 * globals.css), text label always present — never icon-only (see SPEC §10).
 */
export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  function Button(
    { variant = "primary", icon: Icon, full, className = "", children, type = "button", ...rest },
    ref,
  ) {
    const isQuiet = variant === "quiet";
    return (
      <button
        ref={ref}
        type={type}
        className={[
          "inline-flex items-center justify-center gap-2.5 whitespace-nowrap rounded-btn border font-body font-bold leading-tight",
          "text-base transition-colors duration-200 ease-[cubic-bezier(0.33,0.1,0.25,1)]",
          "disabled:cursor-not-allowed disabled:opacity-60",
          isQuiet ? "" : "min-h-12 px-[22px] py-2.5",
          full ? "w-full" : "",
          VARIANTS[variant],
          className,
        ]
          .filter(Boolean)
          .join(" ")}
        {...rest}
      >
        {Icon ? <Icon size={20} strokeWidth={2} aria-hidden="true" /> : null}
        {children}
      </button>
    );
  },
);

/**
 * Pure provider-earnings aggregation for the listener dashboard. Display math
 * only (sums of already-computed integer cents) — the per-session pricing lives
 * in lib/pricing.ts. `nowMs` is injected so the function stays pure/testable.
 */

export interface EarningSessionRow {
  provider_earnings_cents: number;
  ended_at: string | null;
}
export interface EarningTipRow {
  tip_cents: number;
  created_at: string;
}
export interface EarningPayoutRow {
  amount_cents: number;
  status: "scheduled" | "paid";
  scheduled_for: string | null;
}

export interface EarningsBreakdown {
  thisWeekCents: number;
  thisMonthCents: number;
  lifetimeCents: number;
  paidOutCents: number;
  pendingCents: number;
  sessionsThisWeek: number;
  nextPayoutAt: string | null;
}

const WEEK_MS = 7 * 24 * 60 * 60 * 1000;

function startOfMonthMs(nowMs: number): number {
  const d = new Date(nowMs);
  return Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), 1);
}

export function summarizeEarnings({
  sessions,
  tips,
  payouts,
  nowMs,
}: {
  sessions: EarningSessionRow[];
  tips: EarningTipRow[];
  payouts: EarningPayoutRow[];
  nowMs: number;
}): EarningsBreakdown {
  const weekAgo = nowMs - WEEK_MS;
  const monthStart = startOfMonthMs(nowMs);

  let lifetimeCents = 0;
  let thisMonthCents = 0;
  let thisWeekCents = 0;
  let sessionsThisWeek = 0;

  for (const s of sessions) {
    lifetimeCents += s.provider_earnings_cents;
    const endedMs = s.ended_at ? new Date(s.ended_at).getTime() : NaN;
    if (Number.isFinite(endedMs)) {
      if (endedMs >= monthStart) thisMonthCents += s.provider_earnings_cents;
      if (endedMs >= weekAgo) {
        thisWeekCents += s.provider_earnings_cents;
        sessionsThisWeek += 1;
      }
    }
  }

  for (const t of tips) {
    lifetimeCents += t.tip_cents;
    const createdMs = new Date(t.created_at).getTime();
    if (Number.isFinite(createdMs)) {
      if (createdMs >= monthStart) thisMonthCents += t.tip_cents;
      if (createdMs >= weekAgo) thisWeekCents += t.tip_cents;
    }
  }

  let paidOutCents = 0;
  let nextPayoutAt: string | null = null;
  let nextPayoutMs = Infinity;
  for (const p of payouts) {
    if (p.status === "paid") {
      paidOutCents += p.amount_cents;
    } else if (p.status === "scheduled" && p.scheduled_for) {
      const ms = new Date(p.scheduled_for).getTime();
      if (Number.isFinite(ms) && ms >= nowMs && ms < nextPayoutMs) {
        nextPayoutMs = ms;
        nextPayoutAt = p.scheduled_for;
      }
    }
  }

  return {
    thisWeekCents,
    thisMonthCents,
    lifetimeCents,
    paidOutCents,
    pendingCents: Math.max(0, lifetimeCents - paidOutCents),
    sessionsThisWeek,
    nextPayoutAt,
  };
}

/** Format integer cents as a US dollar string, e.g. 2400 → "$24". */
export function formatCents(cents: number): string {
  const dollars = cents / 100;
  const hasFraction = cents % 100 !== 0;
  return dollars.toLocaleString("en-US", {
    style: "currency",
    currency: "USD",
    minimumFractionDigits: hasFraction ? 2 : 0,
    maximumFractionDigits: 2,
  });
}

/** Price summary for a block, e.g. "$24 / 30 min". */
export function formatBlockPrice(cents: number, minutes: number): string {
  return `${formatCents(cents)} / ${minutes} min`;
}

/** Rating to one decimal, e.g. 4.9. */
export function formatRating(avg: number): string {
  return avg.toFixed(1);
}

import Link from "next/link";
import {
