  type LucideIcon,
} from "lucide-react";
import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { StatusBadge } from "@/components/ui/StatusBadge";
import { DashboardHeader } from "@/components/dashboard/DashboardHeader";
import { FavoriteListeners } from "@/components/customer/FavoriteListeners";
import { UpcomingBookings } from "@/components/customer/UpcomingBookings";
import { PastSessionsTable } from "@/components/customer/PastSessionsTable";
import { requireRole } from "@/lib/auth";
import {
  listCustomerBookings,
  listCustomerCompletedSessions,
  listCustomerPayments,
  listCustomerReviews,
  listFavoriteProviders,
  getApprovedProvidersByIds,
} from "@/lib/db/queries";
import { getVoiceIntroSignedUrl } from "@/lib/storage";
