import { t } from "@/lib/i18n";

export const metadata = { title: `${t("account.title")} · ${t("app.name")}` };

export default async function AccountPage({
  searchParams,
}: {
  searchParams: Promise<{ booked?: string }>;
}) {
  const profile = await requireRole("customer");
  const { booked } = await searchParams;

  const [bookings, sessions, payments, reviews, favorites] = await Promise.all([
    listCustomerBookings(profile.id),
    listCustomerCompletedSessions(profile.id),
    listCustomerPayments(profile.id),
    listCustomerReviews(profile.id),
    listFavoriteProviders(profile.id),
  ]);

  // Resolve listener names for bookings + sessions.
  const providerIds = Array.from(
    new Set([
      ...bookings.map((b) => b.provider_id),
      ...sessions.map((s) => s.provider_id),
    ]),
  );
  const providersById = await getApprovedProvidersByIds(providerIds);
  const nameFor = (id: string) => providersById.get(id)?.display_name ?? "—";

  const favoritesWithAudio = await Promise.all(
    favorites.map(async (provider) => ({
      provider,
      audioUrl: await getVoiceIntroSignedUrl(provider.voice_intro_path),
    })),
  );

  // Sort by actual chronology: in-progress first, then "now" bookings, then
  // scheduled by their time — so "Next session" is the soonest, not the latest
  // created.
  const sortKey = (b: (typeof bookings)[number]) =>
    b.status === "in_progress"
      ? 0
      : b.scheduled_at
        ? new Date(b.scheduled_at).getTime()
        : 1; // a "now" booking is imminent
  const upcoming = bookings
    .filter((b) => b.status === "confirmed" || b.status === "in_progress")
    .sort((a, b) => sortKey(a) - sortKey(b))
    .map((b) => ({
      id: b.id,
      providerName: nameFor(b.provider_id),
      blockMinutes: b.block_minutes,
      status: b.status as "confirmed" | "in_progress",
      whenLabel: b.scheduled_at
        ? shortDate(b.scheduled_at)
        : t("account.talkNow"),
    }));

  const next = upcoming[0];

  const reviewedSessionIds = new Set(
    reviews.map((r) => r.session_id).filter(Boolean),
  );
  // Receipts only make sense for completed sessions; an authorized hold on an
  // upcoming booking has no receipt yet.
  const completedBookingIds = new Set(sessions.map((s) => s.booking_id));
  const PAY_STATUS: Record<
    string,
