  const nextScheduled = bookings
    .filter((b) => b.scheduled_at && b.status === "confirmed")
    .sort((a, b) => (a.scheduled_at! < b.scheduled_at! ? -1 : 1))[0];

  const ratingBySession = new Map(
    reviews.filter((r) => r.session_id).map((r) => [r.session_id, r.rating]),
