      {/* Availability + status */}
      <Card as="section" className="flex flex-col gap-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <h2 className="text-h3">{t("provider.availabilityHeading")}</h2>
          <StatusBadge tone={statusCopy.tone} icon={ShieldCheck}>
