        <p className="text-base text-ink-soft">
          {nextScheduled
            ? `${t("provider.nextScheduled")}: ${shortDate(nextScheduled.scheduled_at)} · ${t("provider.minutesShort", { minutes: nextScheduled.block_minutes })}`
            : t("provider.nextScheduledNone")}
        </p>
      </Card>

      {/* At a glance */}
      <section className="flex flex-col gap-4">
        <h2 className="text-h2">{t("provider.glanceHeading")}</h2>
        <div className="grid grid-cols-4 gap-4 max-lg:grid-cols-2 max-sm:grid-cols-1">
          <StatCard
            label={t("provider.earningsHeading")}
            value={formatCents(earnings.thisWeekCents)}
            icon={Wallet}
          />
          <StatCard
            label={t("provider.statPending")}
            value={formatCents(earnings.pendingCents)}
            icon={Clock}
          />
          <StatCard
            label={t("provider.statNextPayout")}
            value={
              earnings.nextPayoutAt
