"use server";

import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { homeForRole } from "@/lib/auth";
import { signInSchema, signUpSchema } from "@/lib/validation/schemas";
import { t } from "@/lib/i18n";
import { type UserRole } from "@/lib/supabase/types";

export interface AuthFormState {
  error?: string;
  fieldErrors?: Record<string, string>;
}

function fieldErrorsFrom(
  issues: { path: (string | number)[]; message: string }[],
): Record<string, string> {
  const out: Record<string, string> = {};
  for (const issue of issues) {
    const key = String(issue.path[0] ?? "");
    if (key && !out[key]) out[key] = issue.message;
  }
  return out;
}

export async function signUpAction(
  _prev: AuthFormState,
  formData: FormData,
): Promise<AuthFormState> {
  const parsed = signUpSchema.safeParse({
    fullName: formData.get("fullName"),
    email: formData.get("email"),
    password: formData.get("password"),
    role: formData.get("role"),
  });

  if (!parsed.success) {
    return { fieldErrors: fieldErrorsFrom(parsed.error.issues) };
  }

  const { fullName, email, password, role } = parsed.data;
  const supabase = await createClient();

  const { error } = await supabase.auth.signUp({
    email,
    password,
    options: {
      data: { role, full_name: fullName },
    },
  });

  if (error) {
    if (
      error.message.toLowerCase().includes("already") ||
      error.code === "user_already_exists"
    ) {
      return { error: t("auth.errorEmailTaken") };
    }
    return { error: t("auth.errorGeneric") };
  }

  // Email confirmation is disabled locally, so a session now exists.
  redirect(homeForRole(role));
}

export async function signInAction(
  _prev: AuthFormState,
  formData: FormData,
): Promise<AuthFormState> {
  const parsed = signInSchema.safeParse({
    email: formData.get("email"),
    password: formData.get("password"),
  });

  if (!parsed.success) {
    return { fieldErrors: fieldErrorsFrom(parsed.error.issues) };
  }

  const supabase = await createClient();
  const { error } = await supabase.auth.signInWithPassword(parsed.data);

  if (error) {
    return { error: t("auth.errorInvalid") };
  }

  const {
    data: { user },
  } = await supabase.auth.getUser();
  let role: UserRole = "customer";
  if (user) {
    const { data } = await supabase
      .from("profiles")
      .select("*")
      .eq("id", user.id)
      .maybeSingle();
    if (data?.role) role = data.role;
  }

  const nextParam = formData.get("next");
  redirect(typeof nextParam === "string" && nextParam.startsWith("/")
    ? nextParam
    : homeForRole(role));
}

export async function signOutAction(): Promise<void> {
  const supabase = await createClient();
  await supabase.auth.signOut();
  redirect("/signin");
}

"use client";

import * as React from "react";
import { Check } from "lucide-react";

export interface ChipProps {
  children: React.ReactNode;
  selected?: boolean;
  onClick?: () => void;
  /** Accessible name when the visible text needs more context for SR users. */
  ariaLabel?: string;
}

/**
 * Toggleable chip. Selection is conveyed by a 2px teal border, tint fill AND a
 * check icon plus aria-pressed — never by color alone (SPEC §10).
 */
export function Chip({ children, selected, onClick, ariaLabel }: ChipProps) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-pressed={!!selected}
      aria-label={ariaLabel}
      className={[
        "inline-flex min-h-11 items-center gap-1.5 rounded-pill px-4 font-body text-sm font-bold",
        "transition-colors duration-200",
        selected
          ? "border-2 border-primary bg-primary-tint text-primary-dark"
          : "border border-border-strong bg-surface text-ink hover:bg-primary-tint/50",
      ].join(" ")}
    >
      {selected ? <Check size={16} strokeWidth={2.5} aria-hidden="true" /> : null}
      {children}
    </button>
  );
}

import * as React from "react";

/**
 * Static, non-interactive label (e.g. a listener's topic). For a toggleable
 * version use <Chip>.
 */
export function Tag({ children }: { children: React.ReactNode }) {
  return (
    <span className="inline-flex items-center rounded-pill border border-border bg-surface-sunk px-3 py-1 text-sm font-semibold text-ink-soft">
      {children}
    </span>
  );
}

/**
 * Domain value lists. These are stored verbatim in the database (providers.topics
 * / languages) and shown as-is, so they live here as canonical data rather than
 * in the UI message catalog.
 */
export const TOPICS = [
  "everyday chat",
  "just listen",
  "grief",
  "books",
  "sports",
  "language practice",
  "night owl",
  "transition",
  "company",
] as const;

export const LANGUAGES = [
  "English",
  "Spanish",
  "Hindi",
  "Arabic",
  "Mandarin",
  "French",
  "Portuguese",
] as const;

export type Topic = (typeof TOPICS)[number];
export type Language = (typeof LANGUAGES)[number];

/** Private Storage bucket for provider voice intros (used client + server). */
export const VOICE_BUCKET = "voice-intros";

/**
 * Time helpers. Kept out of component render bodies so the reads of the current
 * time stay outside React's purity checks.
 */

/** ISO timestamp for `days` ago from now. */
export function isoDaysAgo(days: number): string {
  return new Date(Date.now() - days * 24 * 60 * 60 * 1000).toISOString();
}

/** Current time in epoch ms. */
export function nowEpochMs(): number {
  return Date.now();
}

/** Short US date for a timestamp, e.g. "Jun 8, 2026". */
export function shortDate(iso: string | null): string {
  if (!iso) return "—";
  return new Date(iso).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

/** m:ss from seconds. */
export function durationLabel(seconds: number): string {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${m}:${String(s).padStart(2, "0")}`;
}

import { z } from "zod";

/**
 * Zod schemas for input validation at the boundary (CLAUDE.md rule 5).
 * The M0 subset covers auth; entity schemas are added in M1.
 */

export const roleSchema = z.enum(["customer", "provider"]);
export type SignUpRole = z.infer<typeof roleSchema>;

export const emailSchema = z
  .string()
  .trim()
  .min(1, "Enter your email address.")
  .email("Enter a valid email address.");

export const passwordSchema = z
  .string()
  .min(8, "Use at least 8 characters.")
  .max(72, "That password is too long.");

export const signInSchema = z.object({
  email: emailSchema,
  password: z.string().min(1, "Enter your password."),
});
export type SignInInput = z.infer<typeof signInSchema>;

export const signUpSchema = z.object({
  fullName: z
    .string()
    .trim()
    .min(1, "Enter your name.")
    .max(120, "That name is too long."),
  email: emailSchema,
  password: passwordSchema,
  role: roleSchema,
});
export type SignUpInput = z.infer<typeof signUpSchema>;

/* ===================================================================
   Entity schemas (M1). Shared by the server actions built in M3–M7.
   Money is integer cents; block lengths are fixed at 15 / 30 / 45.
   =================================================================== */

export const BLOCK_MINUTES = [15, 30, 45] as const;
export const blockMinutesSchema = z
  .number()
  .int()
